import {gameIcon,RESEARCH_ICONS} from './ui-art.js?v=30.1';
import {RESEARCH,WEAPON_MULTIPLIERS,weaponTier,weaponCost,researchLevel,researchCost} from './progression.js?v=30.1';
import {weaponCap,researchCap} from './economy.js?v=30.1';
const weaponGate=tier=>['','首通第 1 大关后开放','首通第 3 大关后开放','首通第 5 大关后开放','第 9 大关训练达到 LV.45 后开放'][tier];
const researchGate=level=>['','首通第 3 大关后开放','首通第 6 大关后开放','第 9 大关训练达到 LV.47 后开放'][level];

export function progressionHtml(profile,ship,manifest){
 const tier=weaponTier(profile,ship),cost=weaponCost(tier),materials=profile.materials,wcap=weaponCap(profile),rcap=researchCap(profile);
 return `<span class="selection-label">${gameIcon(manifest,'research')}材料工坊</span><p class="modal-note">蓝图提升当前机体的武器品质；回声数据研究全机体共享节点。强化在下次出击生效。</p><div class="material-wallet"><span>蓝图材料 <b>${materials.blueprint}</b></span><span>回声数据 <b>${materials.data}</b></span></div><section class="forge-card"><div class="forge-heading">${gameIcon(manifest,'upgrade')}<strong>武器品质</strong><b>T${tier} · ×${WEAPON_MULTIPLIERS[tier].toFixed(2)}</b></div><div class="quality-track">${WEAPON_MULTIPLIERS.map((multiplier,i)=>`<span class="${i<=tier?'unlocked':''}">T${i}<small>×${multiplier.toFixed(2)}</small></span>`).join('')}</div>${cost&&tier>=wcap?`<p class="forge-lock">${weaponGate(tier+1)}</p>`:''}${cost?`<p>下一品质 <b>T${tier+1} · ×${WEAPON_MULTIPLIERS[tier+1].toFixed(2)}</b></p><button class="secondary" data-action="forge" ${tier>=wcap||profile.credits<cost.credits||materials.blueprint<cost.blueprint?'disabled':''}>提升品质 · ${cost.blueprint} 蓝图材料 + ${cost.credits} 信用点</button>`:'<p class="growth-max">武器品质已满级</p>'}</section><span class="selection-label">回声研究 · 全机体共享</span><div class="research-grid">${RESEARCH.map(node=>{const level=researchLevel(profile,node.id),price=researchCost(level);return `<section class="forge-card"><div class="forge-heading">${gameIcon(manifest,RESEARCH_ICONS[node.id])}<strong>${node.name[0]}</strong><b>${level} / ${node.max}</b></div><p>${node.note[0]}</p>${price&&level>=rcap?`<p class="forge-lock">${researchGate(level+1)}</p>`:''}<button class="secondary" data-action="research" data-value="${node.id}" ${!price||level>=rcap||profile.credits<price.credits||materials.data<price.data?'disabled':''}>${price?`研究 · ${price.data} 回声数据 + ${price.credits} 信用点`:'研究已满级'}</button></section>`;}).join('')}</div>`;
}
